 268	void installClientWriteHandler(client *c) {
 269	    int ae_barrier = 0;
 270	    /* For the fsync=always policy, we want that a given FD is never
 271	     * served for reading and writing in the same event loop iteration,
 272	     * so that in the middle of receiving the query, and serving it
 273	     * to the client, we'll call beforeSleep() that will do the
 274	     * actual fsync of AOF to disk. the write barrier ensures that. */
 275	    if (server.aof_state == AOF_ON &&
 276	        server.aof_fsync == AOF_FSYNC_ALWAYS)
 277	    {
 278	        ae_barrier = 1;
 279	    }
 280	    if (connSetWriteHandlerWithBarrier(c->conn, sendReplyToClient, ae_barrier) == C_ERR) {
 281	        freeClientAsync(c);
 282	    }
 283	}
