3547	/* This function calls processCommand(), but also performs a few sub tasks
3548	 * for the client that are useful in that context:
3549	 *
3550	 * 1. It sets the current client to the client 'c'.
3551	 * 2. calls commandProcessed() if the command was handled.
3552	 *
3553	 * The function returns C_ERR in case the client was freed as a side effect
3554	 * of processing the command, otherwise C_OK is returned. */
3555	int processCommandAndResetClient(client *c) {
3556	    int deadclient = 0;
3557	    client *old_client = server.current_client;
3558	    server.current_client = c;
3559	    if (processCommand(c) == C_OK) {
3560	        commandProcessed(c);
3561	        /* Update the client's memory to include output buffer growth following the
3562	         * processed command. */
3563	        if (c->conn) updateClientMemUsageAndBucket(c);
3564	    }
3565	
3566	    if (server.current_client == NULL) deadclient = 1;
3567	    /*
3568	     * Restore the old client, this is needed because when a script
3569	     * times out, we will get into this code from processEventsWhileBlocked.
3570	     * Which will cause to set the server.current_client. If not restored
3571	     * we will return 1 to our caller which will falsely indicate the client
3572	     * is dead and will stop reading from its buffer.
3573	     */
3574	    server.current_client = old_client;
3575	    /* performEvictions may flush slave output buffers. This may
3576	     * result in a slave, that may be the active client, to be
3577	     * freed. */
3578	    return deadclient ? C_ERR : C_OK;
3579	}
