3582	/* This function will execute any fully parsed commands pending on
3583	 * the client. Returns C_ERR if the client is no longer valid after executing
3584	 * the command, and C_OK for all other cases. */
3585	int processPendingCommandAndInputBuffer(client *c) {
3586	    /* Notice, this code is also called from 'processUnblockedClients'.
3587	     * But in case of a module blocked client (see RM_Call 'K' flag) we do not reach this code path.
3588	     * So whenever we change the code here we need to consider if we need this change on module
3589	     * blocked client as well */
3590	    if (c->flags & CLIENT_PENDING_COMMAND) {
3591	        c->flags &= ~CLIENT_PENDING_COMMAND;
3592	        if (processCommandAndResetClient(c) == C_ERR) {
3593	            return C_ERR;
3594	        }
3595	    }
3596	
3597	    /* Now process client if it has more data in it's buffer.
3598	     *
3599	     * Note: when a master client steps into this function,
3600	     * it can always satisfy this condition, because its querybuf
3601	     * contains data not applied. */
3602	    if ((c->querybuf && sdslen(c->querybuf) > 0) || c->pending_cmds.ready_len > 0) {
3603	        return processInputBuffer(c);
3604	    }
3605	    return C_OK;
3606	}
