3685	/* This function is called every time, in the client structure 'c', there is
3686	 * more query buffer to process, because we read more data from the socket
3687	 * or because a client was blocked and later reactivated, so there could be
3688	 * pending query buffer, already representing a full command, to process.
3689	 * return C_ERR in case the client was freed during the processing */
3690	int processInputBuffer(client *c) {
3691	    atomicIncr(server.stat_total_client_process_input_buff_events, 1);
3692	
3693	    /* Keep active-client window updates on main-thread paths only (here and
3694	     * in IO-thread handoff processing) to avoid races with serverCron()
3695	     * maintenance of the circular slots. */
3696	    if (c->running_tid == IOTHREAD_MAIN_THREAD_ID)
3697	        statsUpdateActiveClients(c);
3698	
3699	    /* We limit the lookahead for unauthenticated connections to 1.
3700	     * This is both to reduce memory overhead, and to prevent errors: AUTH can
3701	     * affect the handling of succeeding commands. Parsing of "large"
3702	     * unauthenticated multibulk commands is rejected, which would cause those
3703	     * commands to incorrectly return an error to the client. */
3704	    const int lookahead = authRequired(c) ? 1 : server.lookahead;
3705	
3706	    /* Keep processing while there is something in the input buffer */
3707	    while ((c->querybuf && c->qb_pos < sdslen(c->querybuf)) ||
3708	           c->pending_cmds.ready_len > 0)
3709	    {
3710	        /* Immediately abort if the client is in the middle of something. */
3711	        if (c->flags & CLIENT_BLOCKED || c->flags & CLIENT_UNBLOCKED) break;
3712	
3713	        /* Don't process more buffers from clients that have already pending
3714	         * commands to execute in c->argv. */
3715	        if (c->flags & CLIENT_PENDING_COMMAND) break;
3716	
3717	        /* Don't process input from the master while there is a busy script
3718	         * condition on the slave. We want just to accumulate the replication
3719	         * stream (instead of replying -BUSY like we do with other clients) and
3720	         * later resume the processing. */
3721	        if (c->flags & CLIENT_MASTER && isInsideYieldingLongCommand()) break;
3722	
3723	        /* CLIENT_CLOSE_AFTER_REPLY closes the connection once the reply is
3724	         * written to the client. Make sure to not let the reply grow after
3725	         * this flag has been set (i.e. don't process more commands).
3726	         *
3727	         * The same applies for clients we want to terminate ASAP. */
3728	        if (c->flags & (CLIENT_CLOSE_AFTER_REPLY|CLIENT_CLOSE_ASAP)) break;
3729	
3730	        /* Determine if we need to parse more commands from the query buffer.
3731	         * Only parse when there are no ready commands waiting to be processed. */
3732	        const int parse_more = !c->pending_cmds.ready_len;
3733	        int pending_cmd_before_reading = c->pending_cmds.ready_len;
3734	
3735	        /* Parse up to lookahead commands only if we don't have enough ready commands */
3736	        while (parse_more && c->pending_cmds.ready_len < lookahead &&
3737	               c->querybuf && c->qb_pos < sdslen(c->querybuf))
3738	        {
3739	            /* Determine request type when unknown. */
3740	            if (!c->reqtype) {
3741	                if (c->querybuf[c->qb_pos] == '*') {
3742	                    c->reqtype = PROTO_REQ_MULTIBULK;
3743	                } else {
3744	                    c->reqtype = PROTO_REQ_INLINE;
3745	                }
3746	            }
3747	
3748	            pendingCommand *pcmd = NULL;
3749	            if (c->reqtype == PROTO_REQ_INLINE) {
3750	                pcmd = acquirePendingCommand();
3751	                if (processInlineBuffer(c, pcmd) == C_ERR && !pcmd->read_error) {
3752	                    /* If it fails but there are no errors, it means that it might just be
3753	                     * that the desired content cannot be parsed. At this point, we exit and wait for the next time. */
3754	                    freePendingCommand(c, pcmd);
3755	                    break;
3756	                }
3757	            } else if (c->reqtype == PROTO_REQ_MULTIBULK) {
3758	                int incomplete = (c->pending_cmds.len != c->pending_cmds.ready_len);
3759	                if (unlikely(incomplete)) {
3760	                    pcmd = popPendingCommandFromTail(&c->pending_cmds);
3761	                } else {
3762	                    pcmd = acquirePendingCommand();
3763	                }
3764	
3765	                if (processMultibulkBuffer(c, pcmd) == C_ERR && !pcmd->read_error) {
3766	                    /* If it fails but there are no errors, it means that it might just be
3767	                     * that the desired content cannot be parsed. At this point, we exit and wait for the next time. */
3768	                    freePendingCommand(c, pcmd);
3769	                    break;
3770	                }
3771	            } else {
3772	                serverPanic("Unknown request type");
3773	            }
3774	
3775	            addPendingCommand(&c->pending_cmds, pcmd);
3776	            if (unlikely(pcmd->read_error || (pcmd->flags & PENDING_CMD_FLAG_INCOMPLETE)))
3777	                break;
3778	
3779	            if (c->running_tid == IOTHREAD_MAIN_THREAD_ID)
3780	                pcmd->reploff = c->read_reploff - sdslen(c->querybuf) + c->qb_pos;
3781	            else
3782	                pcmd->reploff = c->io_read_reploff - sdslen(c->querybuf) + c->qb_pos;
3783	
3784	            preprocessCommand(c, pcmd);
3785	            resetClientQbufState(c);
3786	        }
3787	
3788	        if (c->pending_cmds.ready_len != pending_cmd_before_reading) {
3789	            int newly_parsed_cmds = c->pending_cmds.ready_len - pending_cmd_before_reading;
3790	            atomicIncr(server.stat_avg_pipeline_length_sum, newly_parsed_cmds);
3791	            atomicIncr(server.stat_avg_pipeline_length_cnt, 1);
3792	
3793	            c->stat_avg_pipeline_length_sum += newly_parsed_cmds;
3794	            c->stat_avg_pipeline_length_cnt++;
3795	        }
3796	
3797	        /* Try to consume the next ready command from the pending command list. */
3798	        if (!c->pending_cmds.ready_len)
3799	            break;
3800	        pendingCommand *curcmd = c->pending_cmds.head;
3801	
3802	        /* We populate the old client fields so we don't have to modify all existing logic to work with pendingCommands */
3803	        c->argc = curcmd->argc;
3804	        c->argv = curcmd->argv;
3805	        c->argv_len = curcmd->argv_len;
3806	        c->net_input_bytes_curr_cmd += curcmd->input_bytes;
3807	        c->reploff_next = curcmd->reploff;
3808	        c->slot = curcmd->slot;
3809	        c->lookedcmd = curcmd->cmd;
3810	        c->read_error = curcmd->read_error;
3811	        c->current_pending_cmd = curcmd;
3812	
3813	        /* Prefetch the command only when more commands have been parsed and we
3814	         * are in the main thread. If running in an IO thread, prefetch will be
3815	         * deferred until the client is processed by the main thread. Skip prefetch
3816	         * if there are too few commands to avoid meaningless prefetching. */
3817	        if (parse_more && c->running_tid == IOTHREAD_MAIN_THREAD_ID &&
3818	            c->pending_cmds.ready_len > 1)
3819	        {
3820	            /* Prefetch the commands. */
3821	            resetCommandsBatch();
3822	            addCommandToBatch(c);
3823	            prefetchCommands();
3824	        }
3825	
3826	        /* Check if the client has a fatal read error that requires stopping processing. */
3827	        if (isClientReadErrorFatal(c)) {
3828	            if (c->running_tid != IOTHREAD_MAIN_THREAD_ID) {
3829	                enqueuePendingClientsToMainThread(c, 0);
3830	            }
3831	            break;
3832	        }
3833	
3834	        /* Multibulk processing could see a <= 0 length. */
3835	        if (!c->argc) {
3836	            /* A naked newline can be sent from masters as a keep-alive, or from slaves to refresh
3837	             * the last ACK time. In that case there's no command to actually execute. */
3838	            prepareForNextCommand(c, 0);
3839	        } else {
3840	            /* If we are in the context of an I/O thread, we can't really
3841	             * execute the command here. All we can do is to flag the client
3842	             * as one that needs to process the command. */
3843	            if (c->running_tid != IOTHREAD_MAIN_THREAD_ID) {
3844	                c->io_flags |= CLIENT_IO_PENDING_COMMAND;
3845	                enqueuePendingClientsToMainThread(c, 0);
3846	                break;
3847	            }
3848	
3849	            /* We are finally ready to execute the command. */
3850	            if (processCommandAndResetClient(c) == C_ERR) {
3851	                /* If the client is no longer valid, we avoid exiting this
3852	                 * loop and trimming the client buffer later. So we return
3853	                 * ASAP in that case. */
3854	                return C_ERR;
3855	            }
3856	        }
3857	    }
3858	
3859	    if (c->flags & CLIENT_MASTER) {
3860	        /* If the client is a master, trim the querybuf to repl_applied,
3861	         * since master client is very special, its querybuf not only
3862	         * used to parse command, but also proxy to sub-replicas.
3863	         *
3864	         * Here are some scenarios we cannot trim to qb_pos:
3865	         * 1. we don't receive complete command from master
3866	         * 2. master client blocked cause of client pause
3867	         * 3. io threads operate read, master client flagged with CLIENT_PENDING_COMMAND
3868	         *
3869	         * In these scenarios, qb_pos points to the part of the current command
3870	         * or the beginning of next command, and the current command is not applied yet,
3871	         * so the repl_applied is not equal to qb_pos. */
3872	        if (c->repl_applied) {
3873	            sdsrange(c->querybuf,c->repl_applied,-1);
3874	            serverAssert(c->qb_pos >= (size_t)c->repl_applied);
3875	            c->qb_pos -= c->repl_applied;
3876	            c->repl_applied = 0;
3877	        }
3878	    } else if (c->qb_pos) {
3879	        /* Trim to pos */
3880	        sdsrange(c->querybuf,c->qb_pos,-1);
3881	        c->qb_pos = 0;
3882	    }
3883	
3884	    /* Update client memory usage after processing the query buffer, this is
3885	     * important in case the query buffer is big and wasn't drained during
3886	     * the above loop (because of partially sent big commands). */
3887	    if (c->running_tid == IOTHREAD_MAIN_THREAD_ID)
3888	        updateClientMemUsageAndBucket(c);
3889	
3890	    return C_OK;
3891	}
