 594	/* The main thread processes the clients from IO threads, these clients may have
 595	 * a complete command to execute or need to be freed. Note that IO threads never
 596	 * free client since this operation access much server data.
 597	 *
 598	 * Please notice that this function may be called reentrantly, i,e, the same goes
 599	 * for handleClientsFromIOThread and processClientsOfAllIOThreads. For example,
 600	 * when processing script command, it may call processEventsWhileBlocked to
 601	 * process new events, if the clients with fired events from the same io thread,
 602	 * it may call this function reentrantly. */
 603	int processClientsFromIOThread(IOThread *t) {
 604	    /* Get the list of clients to process. */
 605	    pthread_mutex_lock(&mainThreadPendingClientsMutexes[t->id]);
 606	    listJoin(mainThreadProcessingClients[t->id], mainThreadPendingClients[t->id]);
 607	    pthread_mutex_unlock(&mainThreadPendingClientsMutexes[t->id]);
 608	    size_t processed = listLength(mainThreadProcessingClients[t->id]);
 609	    if (processed == 0) return 0;
 610	
 611	    int prefetch_clients = 0;
 612	    /* We may call processClientsFromIOThread reentrantly, so we need to
 613	     * reset the prefetching batch, besides, users may change the config
 614	     * of prefetch batch size, so we need to reset the prefetching batch. */
 615	    resetCommandsBatch();
 616	
 617	    listNode *node = NULL;
 618	    while (listLength(mainThreadProcessingClients[t->id])) {
 619	        if (prefetch_clients <= 0) {
 620	            /* Reset the prefetching batch if we have processed all clients. */
 621	            resetCommandsBatch();
 622	            /* Prefetch the commands if no clients in the batch. */
 623	            prefetch_clients = prefetchIOThreadCommands(t);
 624	        }
 625	        prefetch_clients--;
 626	
 627	        /* Each time we pop up only the first client to process to guarantee
 628	         * reentrancy safety. */
 629	        if (node) zfree(node);
 630	        node = listFirst(mainThreadProcessingClients[t->id]);
 631	        listUnlinkNode(mainThreadProcessingClients[t->id], node);
 632	        client *c = listNodeValue(node);
 633	
 634	        /* Make sure the client is neither readable nor writable in io thread to
 635	         * avoid data race. */
 636	        serverAssert(!(c->io_flags & (CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED)));
 637	        serverAssert(!(c->flags & CLIENT_CLOSE_ASAP));
 638	
 639	        /* Let main thread to run it, set running thread id first. */
 640	        c->running_tid = IOTHREAD_MAIN_THREAD_ID;
 641	
 642	        /* Free objects queued by IO thread for deferred freeing. */
 643	        freeClientIODeferredObjects(c, 0);
 644	        tryUnlinkClientFromPendingRefReply(c, 0);
 645	
 646	        /* If a read error occurs, handle it in the main thread first, since we
 647	         * want to print logs about client information before freeing. */
 648	        if (isClientReadErrorFatal(c)) handleClientReadError(c);
 649	
 650	        /* The client is asked to close in IO thread. */
 651	        if (c->io_flags & CLIENT_IO_CLOSE_ASAP) {
 652	            freeClient(c);
 653	            continue;
 654	        }
 655	
 656	        /* Update some client's members while we are in main thread so we avoid
 657	         * data races. */
 658	        updateClientDataFromIOThread(c);
 659	
 660	        /* Check if we need to run a cron job for the client */
 661	        if (runClientCronFromIOThread(c)) continue;
 662	
 663	        /* Process the pending command and input buffer. */
 664	        if (!isClientReadErrorFatal(c) && c->io_flags & CLIENT_IO_PENDING_COMMAND) {
 665	            /* IO-thread reads may enqueue one-by-one complete commands that are
 666	             * executed in main thread without re-entering processInputBuffer().
 667	             * Account this client as active before processing that handoff path. */
 668	            statsUpdateActiveClients(c);
 669	            c->flags |= CLIENT_PENDING_COMMAND;
 670	            if (processPendingCommandAndInputBuffer(c) == C_ERR) {
 671	                /* If the client is no longer valid, it must be freed safely. */
 672	                continue;
 673	            }
 674	        }
 675	
 676	        /* We may have pending replies if io thread may not finish writing
 677	         * reply to client, so we did not put the client in pending write
 678	         * queue. And we should do that first since we may keep the client
 679	         * in main thread instead of returning to io threads. */
 680	        if (!(c->flags & CLIENT_PENDING_WRITE) && clientHasPendingReplies(c))
 681	            putClientInPendingWriteQueue(c);
 682	
 683	        /* The client only can be processed in the main thread, otherwise data
 684	         * race will happen, since we may touch client's data in main thread. */
 685	        if (isClientMustHandledByMainThread(c)) {
 686	            keepClientInMainThread(c);
 687	            continue;
 688	        }
 689	
 690	        /* Handle replica clients in putReplicasInPendingClientsToIOThreads in
 691	         * beforeSleep */
 692	        if (c->flags & CLIENT_SLAVE) continue;
 693	
 694	        /* Remove this client from pending write clients queue of main thread,
 695	         * And some clients may do not have reply if CLIENT REPLY OFF/SKIP. */
 696	        if (c->flags & CLIENT_PENDING_WRITE) {
 697	            c->flags &= ~CLIENT_PENDING_WRITE;
 698	            listUnlinkNode(server.clients_pending_write, &c->clients_pending_write_node);
 699	        }
 700	        c->running_tid = c->tid;
 701	        listLinkNodeHead(mainThreadPendingClientsToIOThreads[c->tid], node);
 702	        node = NULL;
 703	
 704	        /* If there are several clients to process, let io thread handle them ASAP. */
 705	        sendPendingClientsToIOThreadIfNeeded(t, 1);
 706	    }
 707	    if (node) zfree(node);
 708	
 709	    /* Send the clients to io thread without pending size check, since main thread
 710	     * may process clients from other io threads, so we need to send them to the
 711	     * io thread to process in prallel. */
 712	    sendPendingClientsToIOThreadIfNeeded(t, 0);
 713	
 714	    return processed;
 715	}
