    22	/* For main thread */
    23	static list *mainThreadPendingClientsToIOThreads[IO_THREADS_MAX_NUM]; /* Clients to IO threads */
    24	static list *mainThreadProcessingClients[IO_THREADS_MAX_NUM]; /* Clients in processing */
    25	static list *mainThreadPendingClients[IO_THREADS_MAX_NUM]; /* Pending clients from IO threads */
    26	static pthread_mutex_t mainThreadPendingClientsMutexes[IO_THREADS_MAX_NUM]; /* Mutex for pending clients */
    27	static eventNotifier* mainThreadPendingClientsNotifiers[IO_THREADS_MAX_NUM]; /* Notifier for pending clients */
    28	
    29	/* Send the clients to the main thread for processing when the number of clients
    30	 * in pending list reaches IO_THREAD_MAX_PENDING_CLIENTS, or check_size is 0. */
    31	static inline void sendPendingClientsToMainThreadIfNeeded(IOThread *t, int check_size) {
    32	    size_t len = listLength(t->pending_clients_to_main_thread);
    33	    if (len == 0 || (check_size && len < IO_THREAD_MAX_PENDING_CLIENTS)) return;
    34	
    35	    int running = 0, pending = 0;
    36	    pthread_mutex_lock(&mainThreadPendingClientsMutexes[t->id]);
    37	    pending = listLength(mainThreadPendingClients[t->id]);
    38	    listJoin(mainThreadPendingClients[t->id], t->pending_clients_to_main_thread);
    39	    pthread_mutex_unlock(&mainThreadPendingClientsMutexes[t->id]);
    40	    if (!pending) atomicGetWithSync(server.running, running);
    41	
    42	    /* Only notify main thread if it is not running and no pending clients to process,
    43	     * to avoid unnecessary notify/wakeup. If the main thread is running, it will
    44	     * process the clients in beforeSleep. If there are pending clients, we may
    45	     * already notify the main thread if needed. */
    46	    if (!running && !pending) {
    47	        triggerEventNotifier(mainThreadPendingClientsNotifiers[t->id]);
    48	    }
    49	}
    50	
    51	/* When moving a client from IO thread to main thread we may need to update
    52	 * some of its variables as they are duplicated to avoid contention with main
    53	 * thread.
    54	 * For now this is valid only for master or slave clients. */
    55	void updateClientDataFromIOThread(client *c) {
    56	    if (!(c->flags & CLIENT_MASTER) && !(c->flags & CLIENT_SLAVE)) return;
    57	
    58	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
    59	                 c->running_tid == IOTHREAD_MAIN_THREAD_ID);
    60	
    61	    if (c->io_repl_ack_time > c->repl_ack_time) {
    62	        serverAssert(c->flags & CLIENT_SLAVE);
    63	        c->repl_ack_time = c->io_repl_ack_time;
    64	    }
    65	    if (c->io_lastinteraction > c->lastinteraction) {
    66	        serverAssert(c->flags & CLIENT_MASTER);
    67	        c->lastinteraction = c->io_lastinteraction;
    68	    }
    69	    if (c->io_read_reploff > c->read_reploff) {
    70	        serverAssert(c->flags & CLIENT_MASTER);
    71	        c->read_reploff = c->io_read_reploff;
    72	    }
    73	
    74	    /* Update replication buffer referenced node if IO thread has sent some data. */
    75	    if (c->flags & CLIENT_SLAVE && c->ref_repl_buf_node != NULL &&
    76	        (c->io_curr_repl_node != c->ref_repl_buf_node ||
    77	         c->io_curr_block_pos != c->ref_block_pos))
    78	    {
    79	        ((replBufBlock*)listNodeValue(c->ref_repl_buf_node))->refcount--;
    80	        ((replBufBlock*)listNodeValue(c->io_curr_repl_node))->refcount++;
    81	        c->ref_block_pos = c->io_curr_block_pos;
    82	        c->ref_repl_buf_node = c->io_curr_repl_node;
    83	        incrementalTrimReplicationBacklog(REPL_BACKLOG_TRIM_BLOCKS_PER_CALL);
    84	    }
    85	}
    86	
    87	/* Check to see if the client needs any cron jobs run for them. Return 1 if the
    88	 * client should be terminated */
    89	int runClientCronFromIOThread(client *c) {
    90	    if (c->flags & CLIENT_MASTER &&
    91	        c->io_last_repl_cron + 1000 <= server.mstime)
    92	    {
    93	        c->io_last_repl_cron = server.mstime;
    94	        if (replicationCronRunMasterClient()) return 1;
    95	    }
    96	
    97	    /* Run client cron task for the client per second or it is marked as pending cron. */
    98	    if (c->io_last_client_cron + 1000 <= server.mstime ||
    99	        c->io_flags & CLIENT_IO_PENDING_CRON)
   100	    {
   101	        c->io_last_client_cron = server.mstime;
   102	        if (clientsCronRunClient(c)) return 1;
   103	    } else {
   104	        /* Update the client in the mem usage if clientsCronRunClient is not
   105	         * being called, since that function already performs the update. */
   106	        updateClientMemUsageAndBucket(c);
   107	    }
   108	
   109	    return 0;
   110	}
   111	
   112	/* When IO threads read a complete query of clients or want to free clients, it
   113	 * should remove it from its clients list and put the client in the list to main
   114	 * thread, we will send these clients to main thread in IOThreadBeforeSleep. */
   115	void enqueuePendingClientsToMainThread(client *c, int unbind) {
   116	    /* If the IO thread may no longer manage it, such as closing client, we should
   117	     * unbind client from event loop, so main thread doesn't need to do it costly. */
   118	    if (unbind) {
   119	        /* Drop it from the event loop's pending decompression list first, while
   120	         * c->conn->el is still valid. */
   121	        clientCompressionPendingRemove(c);
   122	        connUnbindEventLoop(c->conn);
   123	    }
   124	    /* Just skip if it already is transferred. */
   125	    if (c->io_thread_client_list_node) {
   126	        IOThread *t = &IOThreads[c->tid];
   127	        /* If there are several clients to process, let the main thread handle them ASAP.
   128	         * Since the client being added to the queue may still need to be processed by
   129	         * the IO thread, we must call this before adding it to the queue to avoid
   130	         * races with the main thread. */
   131	        sendPendingClientsToMainThreadIfNeeded(t, 1);
   132	        /* Disable read and write to avoid race when main thread processes. */
   133	        c->io_flags &= ~(CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED);
   134	        /* Remove the client from IO thread, add it to main thread's pending list. */
   135	        listUnlinkNode(t->clients, c->io_thread_client_list_node);
   136	        listLinkNodeTail(t->pending_clients_to_main_thread, c->io_thread_client_list_node);
   137	        c->io_thread_client_list_node = NULL;
   138	
   139	        if (c->io_thread_compression_clients_node) {
   140	            listDelNode(t->compression_clients, c->io_thread_compression_clients_node);
   141	            c->io_thread_compression_clients_node = NULL;
   142	        }
   143	    }
   144	}
   145	
   146	void enqueuePendingClienstToIOThreads(client *c) {
   147	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
   148	                 c->running_tid == IOTHREAD_MAIN_THREAD_ID);
   149	
   150	    if (c->flags & CLIENT_PENDING_WRITE) {
   151	        c->flags &= ~CLIENT_PENDING_WRITE;
   152	        listUnlinkNode(server.clients_pending_write, &c->clients_pending_write_node);
   153	    }
   154	    if (c->flags & CLIENT_SLAVE) {
   155	        serverAssert(c->ref_repl_buf_node != NULL);
   156	
   157	        c->io_repl_ack_time = c->repl_ack_time;
   158	        c->io_curr_repl_node = c->ref_repl_buf_node;
   159	        c->io_curr_block_pos = c->ref_block_pos;
   160	        c->io_bound_repl_node = listLast(server.repl_buffer_blocks);
   161	        c->io_bound_block_pos = ((replBufBlock*)listNodeValue(c->io_bound_repl_node))->used;
   162	    }
   163	    if (c->flags & CLIENT_MASTER) {
   164	        c->io_read_reploff = c->read_reploff;
   165	        c->io_lastinteraction = c->lastinteraction;
   166	    }
   167	
   168	    /* Check here prevents data races with IO thread which may also check
   169	     * this flag. */
   170	    if (!(c->io_flags & CLIENT_IO_COMPRESSION_ENABLED)) {
   171	        if (c->compression_level > 0) {
   172	            if (!clientEnableCompression(c, COMPRESS)) {
   173	                /* Failing to initialize compression is unrecoverable for this
   174	                 * client. Drop it so it can retry. We are on the main thread
   175	                 * (possibly iterating server.slaves), so schedule an async
   176	                 * close to avoid freeing the client under an active iterator. */
   177	                serverLog(LL_WARNING,
   178	                    "Failed to enable compression for client #%llu. Closing connection...",
   179	                    (unsigned long long)c->id);
   180	                freeClientAsync(c);
   180	                freeClientAsync(c);
   181	                return;
   182	            }
   183	        }
   184	        if (c->flags & CLIENT_MASTER) {
   185	            enableMasterClientDecompressionIfNeeded(c);
   186	        }
   187	    }
   188	
   189	    c->running_tid = c->tid;
   190	    listAddNodeHead(mainThreadPendingClientsToIOThreads[c->tid], c);
   191	}
   192	
   193	/* Unbind connection of client from io thread event loop, write and read handlers
   194	 * also be removed, ensures that we can operate the client safely. */
   195	void unbindClientFromIOThreadEventLoop(client *c) {
   196	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
   197	                 c->running_tid == IOTHREAD_MAIN_THREAD_ID);
   198	    /* If the client is not bound to an event loop there is nothing to do,
   199	     * unless the client uses repl compression in which case we need to unlink
   200	     * it from IO Thread compression_clients list. */
   201	    if (!connHasEventLoop(c->conn) && !c->compression_state) return;
   202	
   203	    /* As calling in main thread, we should pause the io thread to make it safe. */
   204	    pauseIOThread(c->tid);
   205	    clientCompressionPendingRemove(c);
   206	    connUnbindEventLoop(c->conn);
   207	    IOThread *t = &IOThreads[c->tid];
   208	    /* We need to remove the client from the compression_clients list so it
   209	     * won't be processed in IOThreadCompressionCron anymore */
   210	    if (c->io_thread_compression_clients_node) {
   211	        listDelNode(t->compression_clients, c->io_thread_compression_clients_node);
   212	        c->io_thread_compression_clients_node = NULL;
   213	        clientDisableCompression(c);
   214	    }
   215	    resumeIOThread(c->tid);
   216	}
