   218	/* When main thread is processing a client from IO thread, and wants to keep it,
   219	 * we should unbind connection of client from io thread event loop first,
   220	 * and then bind the client connection into server's event loop. */
   221	void keepClientInMainThread(client *c) {
   222	    if (c->tid == IOTHREAD_MAIN_THREAD_ID) return;
   223	    serverAssert(c->running_tid == IOTHREAD_MAIN_THREAD_ID);
   224	    /* IO thread no longer manage it. */
   225	    server.io_threads_clients_num[c->tid]--;
   226	    /* Unbind connection of client from io thread event loop. */
   227	    unbindClientFromIOThreadEventLoop(c);
   228	    /* Update the client's data in case it was just fetched from IO thread */
   229	    updateClientDataFromIOThread(c);
   230	    /* Let main thread to run it, rebind event loop and read handler */
   231	    connRebindEventLoop(c->conn, server.el);
   232	    connSetReadHandler(c->conn, readQueryFromClient);
   233	    c->io_flags |= CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED;
   234	    c->tid = IOTHREAD_MAIN_THREAD_ID;
   235	    freeClientDeferredObjects(c, 1); /* Free deferred objects. */
   236	    freeClientIODeferredObjects(c, 1); /* Free IO deferred objects. */
   237	    tryUnlinkClientFromPendingRefReply(c, 0);
   238	    /* Main thread starts to manage it. */
   239	    server.io_threads_clients_num[c->tid]++;
   240	}
   241	
   242	/* If the client is managed by IO thread, we should fetch it from IO thread
   243	 * and then main thread will can process it. Just like IO Thread transfers
   244	 * the client to the main thread for processing. */
   245	void fetchClientFromIOThread(client *c) {
   246	    serverAssert(c->tid != IOTHREAD_MAIN_THREAD_ID &&
   247	                 c->running_tid != IOTHREAD_MAIN_THREAD_ID);
   248	    pauseIOThread(c->tid);
   249	    /* Remove the client from clients list of IO thread or main thread. */
   250	    if (c->io_thread_client_list_node) {
   251	        listDelNode(IOThreads[c->tid].clients, c->io_thread_client_list_node);
   252	        c->io_thread_client_list_node = NULL;
   253	    } else {
   254	        list *clients[5] = {
   255	            IOThreads[c->tid].pending_clients,
   256	            IOThreads[c->tid].pending_clients_to_main_thread,
   257	            mainThreadPendingClients[c->tid],
   258	            mainThreadProcessingClients[c->tid],
   259	            mainThreadPendingClientsToIOThreads[c->tid]
   260	        };
   261	        for (int i = 0; i < 5; i++) {
   262	            listNode *ln = listSearchKey(clients[i], c);
   263	            if (ln) {
   264	                listDelNode(clients[i], ln);
   265	                /* Client only can be in one client list. */
   266	                break;
   267	            }
   268	        }
   269	    }
   270	    /* Unbind connection of client from io thread event loop. */
   271	    clientCompressionPendingRemove(c);
   272	    connUnbindEventLoop(c->conn);
   273	    /* Now main thread can process it. */
   274	    resumeIOThread(c->tid);
   275	
   276	    /* Keep the client in main thread. */
   277	    c->running_tid = IOTHREAD_MAIN_THREAD_ID;
   278	    keepClientInMainThread(c);
   279	}
