   522	/* Prefetch the commands from the IO thread. The return value is the number
   523	 * of clients that have been prefetched. */
   524	int prefetchIOThreadCommands(IOThread *t) {
   525	    int len = listLength(mainThreadProcessingClients[t->id]);
   526	    int to_prefetch = determinePrefetchCount(len);
   527	    if (to_prefetch == 0) return 0;
   528	
   529	    /* Two-phase approach to optimize cache utilization:
   530	     * Phase 1: Issue prefetch hints for client structures
   531	     * Phase 2: Access the now-cached client data and add commands to batch */
   532	    /* Since we double the configured size for better performance,
   533	     * see also `determinePrefetchCount` */
   534	    static client *c[PREFETCH_BATCH_MAX_SIZE*2];
   535	    serverAssert(PREFETCH_BATCH_MAX_SIZE*2 >= to_prefetch );
   536	    int clients = 0;
   537	    listIter li;
   538	    listNode *ln;
   539	    listRewind(mainThreadProcessingClients[t->id], &li);
   540	    /* Phase 1: Issue prefetch instructions for client struct and pending_cmds.
   541	     * These prefetches will bring data into cache asynchronously. */
   542	    for (int i = 0; i < to_prefetch && (ln = listNext(&li)); i++) {
   543	        c[i] = listNodeValue(ln);
   544	        redis_prefetch_read(c[i]);
   545	        redis_prefetch_read(&c[i]->pending_cmds);
   546	        redis_prefetch_read(&c[i]->io_deferred_objects);
   547	    }
   548	    /* Phase 2: Access client data (now likely in cache) and add to batch.
   549	     * Also prefetch additional fields (reply, mem_usage_bucket) that will be
   550	     * needed later during command execution. */
   551	    for (int i = 0; i < to_prefetch; i++) {
   552	        if (addCommandToBatch(c[i]) == C_ERR) break;
   553	        if (c[i]->reply) redis_prefetch_read(c[i]->reply);
   554	        redis_prefetch_read(&c[i]->mem_usage_bucket);
   555	        if (c[i]->io_deferred_objects) redis_prefetch_read(c[i]->io_deferred_objects);
   556	        clients++;
   557	    }
   558	    /* Prefetch the commands in the batch. */
   559	    prefetchCommands();
   560	    return clients;
   561	}
   562	
   563	extern int ProcessingEventsWhileBlocked;
   564	
   565	/* Send the pending clients to the IO thread if the number of pending clients
   566	 * is greater than IO_THREAD_MAX_PENDING_CLIENTS, or if size_check is 0. */
   567	static inline void sendPendingClientsToIOThreadIfNeeded(IOThread *t, int size_check) {
   568	    size_t len = listLength(mainThreadPendingClientsToIOThreads[t->id]);
   569	    if (len == 0 || (size_check && len < IO_THREAD_MAX_PENDING_CLIENTS)) return;
   570	
   571	    /* If AOF fsync policy is always, we should not let io thread handle these
   572	     * clients now since we don't flush AOF buffer to file and sync yet.
   573	     * So these clients will be delayed to send io threads in beforeSleep after
   574	     * flushAppendOnlyFile. 
   575	     * 
   576	     * If we are in processEventsWhileBlocked, we don't send clients to io threads
   577	     * now, we want to update server.events_processed_while_blocked accurately. */
   578	    if (server.aof_fsync != AOF_FSYNC_ALWAYS && !ProcessingEventsWhileBlocked) {
   579	        int running = 0, pending = 0;
   580	        pthread_mutex_lock(&(t->pending_clients_mutex));
   581	        pending = listLength(t->pending_clients);
   582	        listJoin(t->pending_clients, mainThreadPendingClientsToIOThreads[t->id]);
   583	        pthread_mutex_unlock(&(t->pending_clients_mutex));
   584	        if (!pending) atomicGetWithSync(t->running, running);
   585	
   586	        /* Only notify io thread if it is not running and no pending clients to
   587	         * process, to avoid unnecessary notify/wakeup. If the io thread is running,
   588	         * it will process the clients in beforeSleep. If there are pending clients,
   589	         * we may already notify the io thread if needed. */
   590	        if(!running && !pending) triggerEventNotifier(t->pending_clients_notifier);
   591	    }
   592	}
   593	
   594	/* The main thread processes the clients from IO threads, these clients may have
   595	 * a complete command to execute or need to be freed. Note that IO threads never
   596	 * free client since this operation access much server data.
   597	 *
   598	 * Please notice that this function may be called reentrantly, i,e, the same goes
   599	 * for handleClientsFromIOThread and processClientsOfAllIOThreads. For example,
   600	 * when processing script command, it may call processEventsWhileBlocked to
   601	 * process new events, if the clients with fired events from the same io thread,
   602	 * it may call this function reentrantly. */
   603	int processClientsFromIOThread(IOThread *t) {
   604	    /* Get the list of clients to process. */
   605	    pthread_mutex_lock(&mainThreadPendingClientsMutexes[t->id]);
   606	    listJoin(mainThreadProcessingClients[t->id], mainThreadPendingClients[t->id]);
   607	    pthread_mutex_unlock(&mainThreadPendingClientsMutexes[t->id]);
   608	    size_t processed = listLength(mainThreadProcessingClients[t->id]);
   609	    if (processed == 0) return 0;
   610	
   611	    int prefetch_clients = 0;
   612	    /* We may call processClientsFromIOThread reentrantly, so we need to
   613	     * reset the prefetching batch, besides, users may change the config
   614	     * of prefetch batch size, so we need to reset the prefetching batch. */
   615	    resetCommandsBatch();
   616	
   617	    listNode *node = NULL;
   618	    while (listLength(mainThreadProcessingClients[t->id])) {
   619	        if (prefetch_clients <= 0) {
   620	            /* Reset the prefetching batch if we have processed all clients. */
   621	            resetCommandsBatch();
   622	            /* Prefetch the commands if no clients in the batch. */
   623	            prefetch_clients = prefetchIOThreadCommands(t);
   624	        }
   625	        prefetch_clients--;
   626	
   627	        /* Each time we pop up only the first client to process to guarantee
   628	         * reentrancy safety. */
   629	        if (node) zfree(node);
   630	        node = listFirst(mainThreadProcessingClients[t->id]);
   631	        listUnlinkNode(mainThreadProcessingClients[t->id], node);
   632	        client *c = listNodeValue(node);
   633	
   634	        /* Make sure the client is neither readable nor writable in io thread to
   635	         * avoid data race. */
   636	        serverAssert(!(c->io_flags & (CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED)));
   637	        serverAssert(!(c->flags & CLIENT_CLOSE_ASAP));
   638	
   639	        /* Let main thread to run it, set running thread id first. */
   640	        c->running_tid = IOTHREAD_MAIN_THREAD_ID;
   641	
   642	        /* Free objects queued by IO thread for deferred freeing. */
   643	        freeClientIODeferredObjects(c, 0);
   644	        tryUnlinkClientFromPendingRefReply(c, 0);
   645	
   646	        /* If a read error occurs, handle it in the main thread first, since we
   647	         * want to print logs about client information before freeing. */
   648	        if (isClientReadErrorFatal(c)) handleClientReadError(c);
   649	
   650	        /* The client is asked to close in IO thread. */
   651	        if (c->io_flags & CLIENT_IO_CLOSE_ASAP) {
   652	            freeClient(c);
   653	            continue;
   654	        }
   655	
   656	        /* Update some client's members while we are in main thread so we avoid
   657	         * data races. */
   658	        updateClientDataFromIOThread(c);
   659	
   660	        /* Check if we need to run a cron job for the client */
   661	        if (runClientCronFromIOThread(c)) continue;
   662	
   663	        /* Process the pending command and input buffer. */
   664	        if (!isClientReadErrorFatal(c) && c->io_flags & CLIENT_IO_PENDING_COMMAND) {
   665	            /* IO-thread reads may enqueue one-by-one complete commands that are
   666	             * executed in main thread without re-entering processInputBuffer().
   667	             * Account this client as active before processing that handoff path. */
   668	            statsUpdateActiveClients(c);
   669	            c->flags |= CLIENT_PENDING_COMMAND;
   670	            if (processPendingCommandAndInputBuffer(c) == C_ERR) {
   671	                /* If the client is no longer valid, it must be freed safely. */
   672	                continue;
   673	            }
   674	        }
   675	
   676	        /* We may have pending replies if io thread may not finish writing
   677	         * reply to client, so we did not put the client in pending write
   678	         * queue. And we should do that first since we may keep the client
   679	         * in main thread instead of returning to io threads. */
   680	        if (!(c->flags & CLIENT_PENDING_WRITE) && clientHasPendingReplies(c))
   681	            putClientInPendingWriteQueue(c);
   682	
   683	        /* The client only can be processed in the main thread, otherwise data
   684	         * race will happen, since we may touch client's data in main thread. */
   685	        if (isClientMustHandledByMainThread(c)) {
   686	            keepClientInMainThread(c);
   687	            continue;
   688	        }
   689	
   690	        /* Handle replica clients in putReplicasInPendingClientsToIOThreads in
   691	         * beforeSleep */
   692	        if (c->flags & CLIENT_SLAVE) continue;
   693	
   694	        /* Remove this client from pending write clients queue of main thread,
   695	         * And some clients may do not have reply if CLIENT REPLY OFF/SKIP. */
   696	        if (c->flags & CLIENT_PENDING_WRITE) {
   697	            c->flags &= ~CLIENT_PENDING_WRITE;
   698	            listUnlinkNode(server.clients_pending_write, &c->clients_pending_write_node);
   699	        }
   700	        c->running_tid = c->tid;
   701	        listLinkNodeHead(mainThreadPendingClientsToIOThreads[c->tid], node);
   702	        node = NULL;
   703	
   704	        /* If there are several clients to process, let io thread handle them ASAP. */
   705	        sendPendingClientsToIOThreadIfNeeded(t, 1);
   706	    }
   707	    if (node) zfree(node);
   708	
   709	    /* Send the clients to io thread without pending size check, since main thread
   710	     * may process clients from other io threads, so we need to send them to the
   711	     * io thread to process in prallel. */
   712	    sendPendingClientsToIOThreadIfNeeded(t, 0);
   713	
   714	    return processed;
   715	}
   716	
   717	/* When the io thread finishes processing the client with the read event, it will
   717	/* When the io thread finishes processing the client with the read event, it will
   718	 * notify the main thread through event triggering in IOThreadBeforeSleep. The main
   718	 * notify the main thread through event triggering in IOThreadBeforeSleep. The main
   719	 * thread handles the event through this function. */
   719	 * thread handles the event through this function. */
   720	void handleClientsFromIOThread(struct aeEventLoop *el, int fd, void *ptr, int mask) {
   720	void handleClientsFromIOThread(struct aeEventLoop *el, int fd, void *ptr, int mask) {
   721	    UNUSED(el);
   722	    UNUSED(mask);
   723	
   724	    IOThread *t = ptr;
   725	
   726	    /* Handle fd event first. */
   727	    serverAssert(fd == getReadEventFd(mainThreadPendingClientsNotifiers[t->id]));
   728	    handleEventNotifier(mainThreadPendingClientsNotifiers[t->id]);
   729	
   730	    /* Process the clients from IO threads. */
   731	    processClientsFromIOThread(t);
   732	}
   733	
   734	/* In the new threaded io design, one thread may process multiple clients, so when
   735	 * an io thread notifies the main thread of an event, there may be multiple clients
   736	 * with commands that need to be processed. But in the event handler function
   737	 * handleClientsFromIOThread may be blocked when processing the specific command,
   738	 * the previous clients can not get a reply, and the subsequent clients can not be
   739	 * processed, so we need to handle this scenario in beforeSleep. The function is to
   740	 * process the commands of subsequent clients from io threads. And another function
   741	 * sendPendingClientsToIOThreads make sure clients from io thread can get replies.
   742	 * See also beforeSleep.
   743	 * 
   744	 * In beforeSleep, we also call this function to handle the clients that are
   745	 * transferred from io threads without notification. */
   746	int processClientsOfAllIOThreads(void) {
   747	    int processed = 0;
   748	    for (int i = 1; i < server.io_threads_num; i++) {
   749	        processed += processClientsFromIOThread(&IOThreads[i]);
   750	    }
   751	    return processed;
   752	}
   753	
   754	/* After the main thread processes the clients, it will send the clients back to
   755	 * io threads to handle, and fire an event, the io thread handles the event by
   756	 * this function. */
   757	void handleClientsFromMainThread(struct aeEventLoop *ae, int fd, void *ptr, int mask) {
   758	    UNUSED(ae);
   759	    UNUSED(mask);
   760	
   761	    IOThread *t = ptr;
   762	
   763	    /* Handle fd event first. */
   764	    serverAssert(fd == getReadEventFd(t->pending_clients_notifier));
   765	    handleEventNotifier(t->pending_clients_notifier);
   766	
   767	    /* Process the clients from main thread. */
   768	    processClientsFromMainThread(t);
   769	}
   770	
   771	/* Processing clients that have finished executing commands from the main thread.
   772	 * If the client is not binded to the event loop, we should bind it first and
   773	 * install read handler. If the client still has query buffer, we should process
   774	 * the input buffer. If the client has pending reply, we just reply to client,
   775	 * and then install write handler if needed. */
   776	int processClientsFromMainThread(IOThread *t) {
   777	    pthread_mutex_lock(&t->pending_clients_mutex);
   778	    listJoin(t->processing_clients, t->pending_clients);
   779	    pthread_mutex_unlock(&t->pending_clients_mutex);
   780	    size_t processed = listLength(t->processing_clients);
   781	    if (processed == 0) return 0;
   782	
   783	    listIter li;
   784	    listNode *ln;
   785	    listRewind(t->processing_clients, &li);
   786	    while((ln = listNext(&li))) {
   787	        client *c = listNodeValue(ln);
   788	        serverAssert(!(c->io_flags & (CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED)));
   789	        /* Main thread must handle clients with CLIENT_CLOSE_ASAP flag, since
   790	         * we only set io_flags when clients in io thread are freed ASAP. */
   791	        serverAssert(!(c->flags & CLIENT_CLOSE_ASAP));
   792	
   793	        /* Link client in IO thread clients list first. */
   794	        serverAssert(c->io_thread_client_list_node == NULL);
   795	        listUnlinkNode(t->processing_clients, ln);
   796	        listLinkNodeTail(t->clients, ln);
   797	        c->io_thread_client_list_node = listLast(t->clients);
   798	
   799	        /* The client now is in the IO thread, let's free deferred objects. */
   800	        freeClientDeferredObjects(c, 0);
   801	
   802	        /* The client is asked to close, we just let main thread free it. */
   803	        if (c->io_flags & CLIENT_IO_CLOSE_ASAP) {
   804	            enqueuePendingClientsToMainThread(c, 1);
   805	            continue;
   806	        }
   807	
   808	        /* Enable read and write and reset some flags. */
   809	        c->io_flags |= CLIENT_IO_READ_ENABLED | CLIENT_IO_WRITE_ENABLED;
   810	        c->io_flags &= ~(CLIENT_IO_PENDING_COMMAND | CLIENT_IO_PENDING_CRON);
   811	
   812	        /* Only bind once, we never remove read handler unless freeing client. */
   813	        if (!connHasEventLoop(c->conn)) {
   814	            connRebindEventLoop(c->conn, t->el);
   815	            serverAssert(!connHasReadHandler(c->conn));
   816	            connSetReadHandler(c->conn, readQueryFromClient);
   817	        }
   818	
   819	        /* Add the client to the compression clients list. */
   820	        if (c->compression_state != NULL &&
   821	            c->io_thread_compression_clients_node == NULL)
   822	        {
   823	            listAddNodeTail(t->compression_clients, c);
   824	            c->io_thread_compression_clients_node = listLast(t->compression_clients);
   825	        }
   826	
   827	        /* If the client has pending replies, write replies to client. */
   828	        if (clientHasPendingReplies(c)) {
   829	            writeToClient(c, 0);
   830	            if (!(c->io_flags & CLIENT_IO_CLOSE_ASAP) && clientHasPendingReplies(c)) {
   831	                connSetWriteHandler(c->conn, sendReplyToClient);
   832	            }
   833	        }
   834	        /* If everything has been flushed, drop any stale write handler so the IO
   835	         * thread event loop doesn't keep firing writable (EPOLLOUT) on an idle
   836	         * client. */
   837	        if (!(c->io_flags & CLIENT_IO_CLOSE_ASAP) && !clientHasPendingReplies(c)) {
   838	            serverAssert(connHasEventLoop(c->conn));
   839	            connSetWriteHandler(c->conn, NULL);
   840	        }
   841	    }
   842	    /* All clients must are processed. */
   843	    serverAssert(listLength(t->processing_clients) == 0);
   844	    return processed;
   845	}
