  15	/* Replicates the behaviour of run_with_period used in serverCron but for
  16	 * IO threads. IO threads use default Hz for now. */
  17	#define run_with_period_io(_t_, _ms_) _run_with_period((_t_)->cronloops, (_ms_), IO_DEFAULT_HZ)
  18	
  19	/* IO threads. */
  20	IOThread IOThreads[IO_THREADS_MAX_NUM];
  21	
  22	/* For main thread */
  23	static list *mainThreadPendingClientsToIOThreads[IO_THREADS_MAX_NUM]; /* Clients to IO threads */
  24	static list *mainThreadProcessingClients[IO_THREADS_MAX_NUM]; /* Clients in processing */
  25	static list *mainThreadPendingClients[IO_THREADS_MAX_NUM]; /* Pending clients from IO threads */
  26	static pthread_mutex_t mainThreadPendingClientsMutexes[IO_THREADS_MAX_NUM]; /* Mutex for pending clients */
  27	static eventNotifier* mainThreadPendingClientsNotifiers[IO_THREADS_MAX_NUM]; /* Notifier for pending clients */
  28	
  29	/* Send the clients to the main thread for processing when the number of clients
  30	 * in pending list reaches IO_THREAD_MAX_PENDING_CLIENTS, or check_size is 0. */
  31	static inline void sendPendingClientsToMainThreadIfNeeded(IOThread *t, int check_size) {
  32	    size_t len = listLength(t->pending_clients_to_main_thread);
  33	    if (len == 0 || (check_size && len < IO_THREAD_MAX_PENDING_CLIENTS)) return;
  34	
  35	    int running = 0, pending = 0;
  36	    pthread_mutex_lock(&mainThreadPendingClientsMutexes[t->id]);
  37	    pending = listLength(mainThreadPendingClients[t->id]);
  38	    listJoin(mainThreadPendingClients[t->id], t->pending_clients_to_main_thread);
  39	    pthread_mutex_unlock(&mainThreadPendingClientsMutexes[t->id]);
  40	    if (!pending) atomicGetWithSync(server.running, running);
  41	
  42	    /* Only notify main thread if it is not running and no pending clients to process,
  43	     * to avoid unnecessary notify/wakeup. If the main thread is running, it will
  44	     * process the clients in beforeSleep. If there are pending clients, we may
  45	     * already notify the main thread if needed. */
  46	    if (!running && !pending) {
  47	        triggerEventNotifier(mainThreadPendingClientsNotifiers[t->id]);
  48	    }
  49	}
