  87	/* Check to see if the client needs any cron jobs run for them. Return 1 if the
  88	 * client should be terminated */
  89	int runClientCronFromIOThread(client *c) {
  90	    if (c->flags & CLIENT_MASTER &&
  91	        c->io_last_repl_cron + 1000 <= server.mstime)
  92	    {
  93	        c->io_last_repl_cron = server.mstime;
  94	        if (replicationCronRunMasterClient()) return 1;
  95	    }
  96	
  97	    /* Run client cron task for the client per second or it is marked as pending cron. */
  98	    if (c->io_last_client_cron + 1000 <= server.mstime ||
  99	        c->io_flags & CLIENT_IO_PENDING_CRON)
 100	    {
 101	        c->io_last_client_cron = server.mstime;
 102	        if (clientsCronRunClient(c)) return 1;
 103	    } else {
 104	        /* Update the client in the mem usage if clientsCronRunClient is not
 105	         * being called, since that function already performs the update. */
 106	        updateClientMemUsageAndBucket(c);
 107	    }
 108	
 109	    return 0;
 110	}
