 563	extern int ProcessingEventsWhileBlocked;
 564	
 565	/* Send the pending clients to the IO thread if the number of pending clients
 566	 * is greater than IO_THREAD_MAX_PENDING_CLIENTS, or if size_check is 0. */
 567	static inline void sendPendingClientsToIOThreadIfNeeded(IOThread *t, int size_check) {
 568	    size_t len = listLength(mainThreadPendingClientsToIOThreads[t->id]);
 569	    if (len == 0 || (size_check && len < IO_THREAD_MAX_PENDING_CLIENTS)) return;
 570	
 571	    /* If AOF fsync policy is always, we should not let io thread handle these
 572	     * clients now since we don't flush AOF buffer to file and sync yet.
 573	     * So these clients will be delayed to send io threads in beforeSleep after
 574	     * flushAppendOnlyFile. 
 575	     * 
 576	     * If we are in processEventsWhileBlocked, we don't send clients to io threads
 577	     * now, we want to update server.events_processed_while_blocked accurately. */
 578	    if (server.aof_fsync != AOF_FSYNC_ALWAYS && !ProcessingEventsWhileBlocked) {
 579	        int running = 0, pending = 0;
 580	        pthread_mutex_lock(&(t->pending_clients_mutex));
 581	        pending = listLength(t->pending_clients);
 582	        listJoin(t->pending_clients, mainThreadPendingClientsToIOThreads[t->id]);
 583	        pthread_mutex_unlock(&(t->pending_clients_mutex));
 584	        if (!pending) atomicGetWithSync(t->running, running);
 585	
 586	        /* Only notify io thread if it is not running and no pending clients to
 587	         * process, to avoid unnecessary notify/wakeup. If the io thread is running,
 588	         * it will process the clients in beforeSleep. If there are pending clients,
 589	         * we may already notify the io thread if needed. */
 590	        if(!running && !pending) triggerEventNotifier(t->pending_clients_notifier);
 591	    }
 592	}
