3893	void readQueryFromClient(connection *conn) {
3894	    client *c = connGetPrivateData(conn);
3895	    int nread, big_arg = 0;
3896	    size_t qblen, readlen;
3897	
3898	    /* We have to read compressed data but compression for this client is
3899	     * currently disabled. This could happened f.e when client was just fetched
3900	     * to main thread. */
3901	    int pending_compression_read = c->compression_state &&
3902	                                   !(c->io_flags & CLIENT_IO_COMPRESSION_ENABLED);
3903	
3904	    if (!(c->io_flags & CLIENT_IO_READ_ENABLED) || pending_compression_read) {
3905	        atomicSetWithSync(c->pending_read, 1);
3906	        return;
3907	    } else if (server.io_threads_num > 1) {
3908	        atomicSetWithSync(c->pending_read, 0);
3909	    }
3910	
3911	    c->read_error = 0;
3912	
3913	    c->stat_total_read_events++;
3914	
3915	    /* Update the number of reads of io threads on server */
3916	    atomicIncr(IOThreads[c->running_tid].io_reads_processed, 1);
3917	
3918	    readlen = PROTO_IOBUF_LEN;
3919	    /* If this is a multi bulk request, and we are processing a bulk reply
3920	     * that is large enough, try to maximize the probability that the query
3921	     * buffer contains exactly the SDS string representing the object, even
3922	     * at the risk of requiring more read(2) calls. This way the function
3923	     * processMultiBulkBuffer() can avoid copying buffers to create the
3924	     * Redis Object representing the argument. */
3925	    if (c->reqtype == PROTO_REQ_MULTIBULK && c->multibulklen && c->bulklen != -1
3926	        && c->bulklen >= PROTO_MBULK_BIG_ARG)
3927	    {
3928	        /* For big argv, the client always uses its private query buffer.
3929	         * Using the reusable query buffer would eventually expand it beyond 32k,
3930	         * causing the client to take ownership of the reusable query buffer. */
3931	        if (!c->querybuf) c->querybuf = sdsempty();
3932	
3933	        ssize_t remaining = (size_t)(c->bulklen+2)-(sdslen(c->querybuf)-c->qb_pos);
3934	        big_arg = 1;
3935	
3936	        /* Note that the 'remaining' variable may be zero in some edge case,
3937	         * for example once we resume a blocked client after CLIENT PAUSE. */
3938	        if (remaining > 0) readlen = remaining;
3939	
3940	        /* Master client needs expand the readlen when meet BIG_ARG(see #9100),
3941	         * but doesn't need align to the next arg, we can read more data. */
3942	        if (c->flags & CLIENT_MASTER && readlen < PROTO_IOBUF_LEN)
3943	            readlen = PROTO_IOBUF_LEN;
3944	    } else if (c->querybuf == NULL) {
3945	        if (unlikely(thread_reusable_qb_used)) {
3946	            /* The reusable query buffer is already used by another client,
3947	             * switch to using the client's private query buffer. This only
3948	             * occurs when commands are executed nested via processEventsWhileBlocked(). */
3949	            c->querybuf = sdsnewlen(NULL, PROTO_IOBUF_LEN);
3950	            sdsclear(c->querybuf);
3951	        } else {
3952	            /* Create the reusable query buffer if it doesn't exist. */
3953	            if (!thread_reusable_qb) {
3954	                thread_reusable_qb = sdsnewlen(NULL, PROTO_IOBUF_LEN);
3955	                sdsclear(thread_reusable_qb);
3956	            }
3957	
3958	            /* Assign the reusable query buffer to the client and mark it as in use. */
3959	            serverAssert(sdslen(thread_reusable_qb) == 0);
3960	            c->querybuf = thread_reusable_qb;
3961	            c->io_flags |= CLIENT_IO_REUSABLE_QUERYBUFFER;
3962	            thread_reusable_qb_used = 1;
3963	        }
3964	    }
3965	
3966	    qblen = sdslen(c->querybuf);
3967	    if (!(c->flags & CLIENT_MASTER) && // master client's querybuf can grow greedy.
3968	        (big_arg || sdsalloc(c->querybuf) < PROTO_IOBUF_LEN)) {
3969	        /* When reading a BIG_ARG we won't be reading more than that one arg
3970	         * into the query buffer, so we don't need to pre-allocate more than we
3971	         * need, so using the non-greedy growing. For an initial allocation of
3972	         * the query buffer, we also don't wanna use the greedy growth, in order
3973	         * to avoid collision with the RESIZE_THRESHOLD mechanism. */
3974	        c->querybuf = sdsMakeRoomForNonGreedy(c->querybuf, readlen);
3975	        /* We later set the peak to the used portion of the buffer, but here we over
