2839	/* Write data in output buffers to client. Return C_OK if the client
2840	 * is still valid after the call, C_ERR if it was freed because of some
2841	 * error.  If handler_installed is set, it will attempt to clear the
2842	 * write event.
2843	 *
2844	 * This function is called by threads, but always with handler_installed
2845	 * set to 0. So when handler_installed is set to 0 the function must be
2846	 * thread safe. */
2847	int writeToClient(client *c, int handler_installed) {
2848	    if (!(c->io_flags & CLIENT_IO_WRITE_ENABLED)) return C_OK;
2849	    /* Update the number of writes of io threads on server */
2850	    atomicIncr(IOThreads[c->running_tid].io_writes_processed, 1);
2851	
2852	    ssize_t nwritten = 0, totwritten = 0;
2853	    const int is_slave = clientTypeIsSlave(c);
2854	
2855	    if (unlikely(is_slave)) {
2856	        /* We send as much as possible if the client is
2857	         * a slave (otherwise, on high-speed traffic, the
2858	         * replication buffer will grow indefinitely) */
2859	        while(_clientHasPendingRepliesSlave(c)) {
2860	            int ret = _writeToClientSlave(c, &nwritten);
2861	            if (ret == C_ERR) break;
2862	            totwritten += nwritten;
2863	        }
2864	        atomicIncr(server.stat_net_repl_output_bytes, totwritten);
2865	    } else {
2866	        /* If we reach this block and client is marked with CLIENT_SLAVE flag
2867	         * it's because it's a MONITOR/slot-migration client, which are marked
2868	         * as replicas, but exposed as normal clients */
2869	        const int is_normal_client = !(c->flags & CLIENT_SLAVE);
2870	        while (_clientHasPendingRepliesNonSlave(c)) {
2871	            int ret = _writeToClientNonSlave(c, &nwritten);
2872	            if (ret == C_ERR) break;
2873	            totwritten += nwritten;
2874	            /* Note that we avoid to send more than NET_MAX_WRITES_PER_EVENT
2875	             * bytes, in a single threaded server it's a good idea to serve
2876	             * other clients as well, even if a very large request comes from
2877	             * super fast link that is always able to accept data (in real world
2878	             * scenario think about 'KEYS *' against the loopback interface).
2879	             *
2880	             * However if we are over the maxmemory limit we ignore that and
2881	             * just deliver as much data as it is possible to deliver.
2882	             *
2883	             * Moreover, we also send as much as possible if the client is
2884	             * a slave (covered above) or a monitor (covered here).
2885	             * (otherwise, on high-speed traffic, the
2886	             * output buffer will grow indefinitely) */
2887	            if (totwritten > NET_MAX_WRITES_PER_EVENT &&
2888	                (server.maxmemory == 0 ||
2889	                zmalloc_used_memory() < server.maxmemory) &&
2890	                is_normal_client) break;
2891	        }
2892	        atomicIncr(server.stat_net_output_bytes, totwritten);
2893	    }
2894	    c->net_output_bytes += totwritten;
2895	
2896	    if (nwritten == -1) {
2897	        if (connGetState(c->conn) != CONN_STATE_CONNECTED) {
2898	            serverLog(LL_VERBOSE,
2899	                "Error writing to client: %s", connGetLastError(c->conn));
2900	            freeClientAsync(c);
2901	            return C_ERR;
2902	        }
2903	    }
2904	    if (totwritten > 0) {
2905	        /* For clients representing masters we don't count sending data
2906	         * as an interaction, since we always send REPLCONF ACK commands
2907	         * that take some time to just fill the socket output buffer.
2908	         * We just rely on data / pings received for timeout detection. */
2909	        if (!(c->flags & CLIENT_MASTER)) c->lastinteraction = server.unixtime;
2910	    }
2911	    if (!clientHasPendingReplies(c)) {
2912	        c->sentlen = 0;
2913	        /* Note that writeToClient() is called in a threaded way, but
2914	         * aeDeleteFileEvent() is not thread safe: however writeToClient()
2915	         * is always called with handler_installed set to 0 from threads
2916	         * so we are fine. */
2917	        if (handler_installed) {
2918	            /* IO Thread also can do that now. */
2919	            connSetWriteHandler(c->conn, NULL);
2920	        }
2921	
2922	        /* Close connection after entire reply has been sent. */
2923	        if (c->flags & CLIENT_CLOSE_AFTER_REPLY) {
2924	            freeClientAsync(c);
2925	            return C_ERR;
2926	        }
2927	
2928	        /* Remove client from pending referenced reply clients list. */
2929	        if (c->running_tid == IOTHREAD_MAIN_THREAD_ID)
2930	            tryUnlinkClientFromPendingRefReply(c, 1);
2931	
2932	        /* If replica client has sent all the replication data it knows about
2933	         * we send it to main thread so it can pick up new repl data ASAP.
2934	         * Note, that we keep it in IO thread in case we have a pending ACK read. */
2935	        if (c->flags & CLIENT_SLAVE && c->running_tid != IOTHREAD_MAIN_THREAD_ID) {
2936	            if (!replicaFromIOThreadHasPendingRead(c))
2937	                enqueuePendingClientsToMainThread(c, 0);
2938	        }
2939	    }
2940	    /* Update client's memory usage after writing.
2941	     * Since this isn't thread safe we do this conditionally. */
2942	    if (c->running_tid == IOTHREAD_MAIN_THREAD_ID) {
2943	        updateClientMemUsageAndBucket(c);
2944	    }
2945	    return C_OK;
2946	}
