2954	/* This function is called just before entering the event loop, in the hope
2955	 * we can just write the replies to the client output buffer without any
2956	 * need to use a syscall in order to install the writable event handler,
2957	 * get it called, and so forth. */
2958	int handleClientsWithPendingWrites(void) {
2959	    listIter li;
2960	    listNode *ln;
 285	/* This function puts the client in the queue of clients that should write
 286	 * their output buffers to the socket. Note that it does not *yet* install
 287	 * the write handler, to start clients are put in a queue of clients that need
 288	 * to write, so we try to do that before returning in the event loop (see the
 289	 * handleClientsWithPendingWrites() function).
 290	 * If we fail and there is more data to write, compared to what the socket
 291	 * buffers can hold, then we'll really install the handler. */
 292	void putClientInPendingWriteQueue(client *c) {
 293	    /* Schedule the client to write the output buffers to the socket only
 294	     * if not already done and, for slaves, if the slave can actually receive
 295	     * writes at this stage. */
 296	    if (!(c->flags & CLIENT_PENDING_WRITE) &&
 297	        (c->replstate == REPL_STATE_NONE ||
 298	         c->replstate == SLAVE_STATE_SEND_BULK_AND_STREAM ||
 299	         (c->replstate == SLAVE_STATE_ONLINE && !c->repl_start_cmd_stream_on_ack)))
 300	    {
 301	        /* Here instead of installing the write handler, we just flag the
 302	         * client and put it into a list of clients that have something
 303	         * to write to the socket. This way before re-entering the event
 304	         * loop, we can try to directly write to the client sockets avoiding
 305	         * a system call. We'll only really install the write handler if
 306	         * we'll not be able to write the whole reply at once. */
 307	        c->flags |= CLIENT_PENDING_WRITE;
 308	        listLinkNodeHead(server.clients_pending_write, &c->clients_pending_write_node);
 309	    }
