 754	/* After the main thread processes the clients, it will send the clients back to
 755	 * io threads to handle, and fire an event, the io thread handles the event by
 756	 * this function. */
 757	void handleClientsFromMainThread(struct aeEventLoop *ae, int fd, void *ptr, int mask) {
 758	    UNUSED(ae);
 759	    UNUSED(mask);
 760	
 761	    IOThread *t = ptr;
 762	
 763	    /* Handle fd event first. */
 764	    serverAssert(fd == getReadEventFd(t->pending_clients_notifier));
 765	    handleEventNotifier(t->pending_clients_notifier);
 766	
 767	    /* Process the clients from main thread. */
 768	    processClientsFromMainThread(t);
