 847	void IOThreadBeforeSleep(struct aeEventLoop *el) {
 847	void IOThreadBeforeSleep(struct aeEventLoop *el) {
 848	    IOThread *t = el->privdata[0];
 849	
 850	    /* Handle pending data(typical TLS). */
 851	    connTypeProcessPendingData(el);
 852	    /* Drain any buffered decompressed replication data (see client_comp.c). */
 853	    clientCompressionProcessPendingData(el);
 854	
 855	    /* If any connection type(typical TLS) or compression still has
 856	     * pending unread data don't sleep at all. */
 857	    int dont_sleep = connTypeHasPendingData(el) || clientCompressionHasPendingData(el);
 858	
 859	    /* Process clients from main thread, since the main thread may deliver clients
 860	     * without notification during IO thread processing events. */
 861	    if (processClientsFromMainThread(t) > 0) {
 862	        /* If there are clients that are processed, we should not sleep since main
 863	         * thread may want to continue deliverring clients without notification, so
 864	         * IO thread can process them ASAP, and the main thread can avoid unnecessary
 865	         * notification (write fd and wake up) is costly. */
 866	        dont_sleep = 1;
 867	    }
 868	    if (!dont_sleep) {
 869	        atomicSetWithSync(t->running, 0); /* Not running if going to sleep. */
 870	        /* Try to process clients from main thread again, since before we set
 871	         * running to 0, the main thread may deliver clients to this io thread. */
 872	        processClientsFromMainThread(t);
 873	    }
 874	    aeSetDontWait(t->el, dont_sleep);
 875	
 876	    /* Check if i am being paused, pause myself and resume. */
 877	    handlePauseAndResume(t);
 878	
 879	    /* Send clients to main thread to process, we don't check size here since
 880	     * we want to send all clients to main thread before going to sleeping. */
 881	    sendPendingClientsToMainThreadIfNeeded(t, 0);
 882	}
