 884	void IOThreadAfterSleep(struct aeEventLoop *el) {
 885	    IOThread *t = el->privdata[0];
 886	
 887	    /* Set the IO thread to running state, so the main thread can deliver
 888	     * clients to it without extra notifications. */
 889	    atomicSetWithSync(t->running, 1);
 890	}
