 913	void IOThreadCompressionCron(IOThread *t) {
 914	    if (listLength(t->compression_clients) == 0) return;
 915	
 916	    listIter li;
 917	    listNode *ln;
 918	    listRewind(t->compression_clients, &li);
 919	    /* TODO: if compression is generalized for all types of clients this cron
 920	     * will need to only process a portion of the clients (similar to
 921	     * IOThreadClientsCron) for performance reasons. I.e in such case the
 922	     * clientHasPendingCompressionFlush check may be moved directly to
 923	     * IOThreadClientsCron. */
 924	    while ((ln = listNext(&li))) {
 925	        client *c = listNodeValue(ln);
 926	
 927	        if (c->io_flags & CLIENT_IO_CLOSE_ASAP) continue;
 928	        serverAssert(c->compression_state);
 929	
 930	        /* Backstop flush. Data is normally flushed as soon as a replica catches
 931	         * up (see _writeToClientSlaveInIOThread), but this bounds latency for
 932	         * anything still buffered (including compressed output left unwritten by
 933	         * a full socket) once compression_max_latency ms have passed, or drives
 934	         * an in-progress flush to completion. */
 935	        if (clientHasPendingCompressionFlush(c)) {
 936	            /* Only master/replica clients support client compression for now. */
 937	            serverAssert(c->flags & CLIENT_SLAVE);
 938	
 939	            int written = 0;
 940	            int err = clientCompressAndWrite(c, &written, 1);
 941	            if (err) {
 942	                if (connGetState(c->conn) != CONN_STATE_CONNECTED)
 943	                    freeClientAsync(c);
 944	                continue;
 945	            }
 946	
 947	            if (written > 0) {
 948	                c->net_output_bytes += written;
 949	                atomicIncr(server.stat_net_repl_output_bytes, written);
 950	            }
 951	        }
 952	    }
