 955	/* This is the IO thread timer interrupt, IO_DEFAULT_HZ times per second.
 956	 * The current responsibility is to detect clients that have been stuck in the
 957	 * IO thread for too long and hand them over to the main thread for handling. */
 958	int IOThreadCron(struct aeEventLoop *eventLoop, long long id, void *clientData) {
